    },
    {
      "factor": "Hedged Language",
      "polarity": -1,
      "reason_headline": "Ambiguous language in trade update",
      "reason_detailed": "The agent's trade update to Amy includes estimated profit and risk level, but the language used is somewhat ambiguous and lacks specific details."
